package be.winnetrie.mod.simpleserverutilities.kits;
import be.winnetrie.mod.simpleserverutilities.SimpleServerUtilities;import be.winnetrie.mod.simpleserverutilities.network.KitContentsResultPayload;import be.winnetrie.mod.simpleserverutilities.network.KitContentsSavePayload;import be.winnetrie.mod.simpleserverutilities.permission.PermissionKeys;import be.winnetrie.mod.simpleserverutilities.permission.PermissionService;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.SimpleContainer;import net.minecraft.world.SimpleMenuProvider;import net.neoforged.neoforge.network.PacketDistributor;import net.neoforged.neoforge.network.handling.IPayloadContext;
public final class KitEditorService{private KitEditorService(){}public static boolean open(ServerPlayer p,String kitId){if(!canAdmin(p)||SimpleServerUtilities.KITS.definition(kitId)==null)return false;SimpleContainer ghost=new SimpleContainer(9);var items=SimpleServerUtilities.KITS.items(kitId,p.level().registryAccess());for(int i=0;i<Math.min(9,items.size());i++)ghost.setItem(i,items.get(i).copy());p.openMenu(new SimpleMenuProvider((containerId,inventory,ignored)->new KitEditorMenu(containerId,inventory,ghost,kitId),Component.literal("Kit contents — "+kitId)),buf->buf.writeUtf(kitId,64));return true;}public static void save(KitContentsSavePayload payload,IPayloadContext context){if(!(context.player() instanceof ServerPlayer p))return;boolean ok=false;String msg;try{if(!canAdmin(p))throw new IllegalArgumentException("Kit administration denied.");if(!(p.containerMenu instanceof KitEditorMenu menu)||menu.containerId!=payload.containerId())throw new IllegalArgumentException("Kit editor is no longer open.");SimpleServerUtilities.KITS.setItems(menu.kitId(),menu.copies(),p.level().registryAccess());ok=true;msg="Kit contents saved.";}catch(Exception ex){msg=ex.getMessage()==null?"Kit contents could not be saved.":ex.getMessage();}PacketDistributor.sendToPlayer(p,new KitContentsResultPayload(ok,msg,payload.requestId()));}private static boolean canAdmin(ServerPlayer p){return PermissionService.isAdmin(p)&&PermissionService.getBoolean(p,PermissionKeys.KITS_ADMIN,false);}}
